import sys

def main():
    input_line = sys.stdin.readline().strip()
    totalIntervals, thresholdCount, multiplier = map(int, input_line.split())

    MOD = 998244353

    def invs(n, p):
        res = [0] * n
        res[1] = 1
        for i in range(2, n):
            res[i] = (p - (p // i) * res[p % i] % p) % p
        return res

    inverses = invs(2 * totalIntervals + 3, MOD)

    dpTable = [[0] * (totalIntervals + 1) for _ in range(2 * totalIntervals + 1)]
    # Initialize DP
    dpTable[0][1] = 1

    def computeDP(dp, n, invs, mod):
        for step in range(1, 2 * n):
            maxPrev = min(2 * n - step, step)
            maxNext = min(2 * n - step - 1, step + 1)
            for activeCount in range(maxPrev + 1):
                if dp[step - 1][activeCount] != 0:
                    if activeCount > 0:
                        dp[step][activeCount - 1] = (dp[step][activeCount - 1] + dp[step - 1][activeCount] * activeCount % mod * invs[2 * n - step]) % mod
                    if activeCount < maxNext:
                        dp[step][activeCount + 1] = (dp[step][activeCount + 1] + dp[step - 1][activeCount] * (2 * n - step - activeCount) % mod * invs[2 * n - step]) % mod

    computeDP(dpTable, totalIntervals, inverses, MOD)

    def calculateFinalAnswer(dp, n, threshold, multiplier, invs, mod):
        answer = 0
        for i in range(2 * n):
            for j in range(threshold, n + 1):
                answer = (answer + dp[i][j]) % mod
        answer = answer * multiplier % mod * invs[2 * n + 1] % mod
        return answer

    finalAnswer = calculateFinalAnswer(dpTable, totalIntervals, thresholdCount, multiplier, inverses, MOD)
    print(finalAnswer)

if __name__ == "__main__":
    main()

